// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address payable receiver) public {
        // The contract holds a fixed amount of ether; the fuzzer chooses the amount to send.
        vm.deal(address(c), 1 ether);
        // Admissible domain: an over-budget send to a plain EOA (no code) that would accept ETH.
        vm.assume(amount > address(c).balance);
        vm.assume(receiver != address(0) && address(receiver).code.length == 0);
        vm.assume(receiver != address(this));

        // Owner of c is the test contract (deployer), so msg.sender already matches; drive sendTo.
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: an owner send of an amount exceeding c's balance must revert
        // because the ETH transfer fails. The mutant (transfer removed) never reverts.
        assertTrue(!ok, "over-budget sendTo must revert");
    }
}
